insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('664dcc4e-21a6-4036-9827-6886759877b7', '901aa111-b123-4c45-9a67-abcde0000001', 1, 'customer', 'Hi, I''d love to plan an indulgent dinner for two tonight-can you help me mix seafood and spice?', 0.95);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('3fd1b20f-d758-4a17-b92a-38aeb5e89e22', '901aa111-b123-4c45-9a67-abcde0000001', 2, 'agent', 'Absolutely! I''ll reserve Bertram''s alcove and pair the kothmir salmon with our peacock cocktail.', 0.97);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('e7d215f1-4eae-4aa7-8cc1-6ccba07c274f', '901aa111-b123-4c45-9a67-abcde0000001', 3, 'customer', 'Perfect, please add the gulab jamun to finish-my partner adores it.', 0.96);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('3a521109-f300-4181-b6c4-b7ca2ac30c9f', '901aa112-b123-4c45-9a67-abcde0000002', 1, 'customer', 'We''re celebrating a product launch-can you surprise us with the chef''s favorites?', 0.94);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('5492e769-1cef-4507-b9ab-faf27bd98680', '901aa112-b123-4c45-9a67-abcde0000002', 2, 'agent', 'I''ll layer butter chicken, goat biryani, and a custom cocktail flight, then apply your VIP tasting credit.', 0.98);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('47838a28-34c7-4e0a-8185-a7152b47d567', '901aa112-b123-4c45-9a67-abcde0000002', 3, 'customer', 'That''s why I call you first-lock it in for eight o''clock.', 0.96);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('1eb513d7-0749-4e10-b023-69d7bb32a519', '901aa113-b123-4c45-9a67-abcde0000003', 1, 'customer', 'I need hearty dishes for eight execs-think biryani, butter chicken, and desserts.', 0.92);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('217de85b-0fe8-48e8-9306-278d43b0b344', '901aa113-b123-4c45-9a67-abcde0000003', 2, 'agent', 'I''ll arrange a delivery with naan baskets, cake, and apply your celebration credit.', 0.95);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('48cdd7ee-63c9-414f-8c33-2ab3d360b378', '901aa113-b123-4c45-9a67-abcde0000003', 3, 'customer', 'Perfect, have it staged by 6:45 with serving utensils.', 0.93);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('9739b01a-4a06-4516-8d30-ab247291e785', '901aa114-b123-4c45-9a67-abcde0000004', 1, 'customer', 'We''re hosting investors-need a private room with curated curries and cocktails.', 0.93);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('1e648a2c-291e-4e4f-8728-b5a2949b2d65', '901aa114-b123-4c45-9a67-abcde0000004', 2, 'agent', 'I''ll design a family-style spread, assign two servers, and take $100 off for the event package.', 0.97);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('c6467e07-1c6c-4662-9d3c-6f824383e5aa', '901aa114-b123-4c45-9a67-abcde0000004', 3, 'customer', 'Send the final BEO tonight so I can loop in facilities.', 0.94);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('a869c19f-2af5-479d-8bd5-6d8c8fb5e666', '901aa115-b123-4c45-9a67-abcde0000005', 1, 'customer', 'Turn the vindaloo heat to eleven-I''m chasing the chef special.', 0.93);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('5645f153-4080-4935-9809-484ba767c1c4', '901aa115-b123-4c45-9a67-abcde0000005', 2, 'agent', 'You got it. I''ll flag the kitchen for maximum heat and add cooling naan and gulab jamun.', 0.95);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('f650c11c-e53b-4526-884b-2682fdeba62a', '901aa115-b123-4c45-9a67-abcde0000005', 3, 'customer', 'Love it. Pair with two peacock cocktails and let''s go.', 0.94);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('524d9710-3ab3-4be8-b3f0-5dafa51a3924', '901aa116-b123-4c45-9a67-abcde0000006', 1, 'customer', 'We''re throwing a backyard birthday-need enough curry and cocktails for twenty-four.', 0.91);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('dd59ff27-de7d-4794-b6d5-c957a64e92c4', '901aa116-b123-4c45-9a67-abcde0000006', 2, 'agent', 'I''ll stage mixed protein curries, trays of naan, and batch cocktails-applying the private buyout credit.', 0.96);
insert into public.interaction_transcripts (transcript_id, interaction_id, turn_index, speaker, content, confidence) values ('2274b6dc-bf1d-4b60-8640-29c5ded8c956', '901aa116-b123-4c45-9a67-abcde0000006', 3, 'customer', 'Amazing. Include six vegetarian mains for my in-laws.', 0.94);
